'use client';

import { useState } from 'react';
import { Outfit } from 'next/font/google';
import './globals.css';
import Navbar from '@/components/Navbar';
import Footer from '@/components/Footer';
import ContactModal from '@/components/ContactModal';
import { ModalProvider, useModal } from '@/contexts/ModalContext';
import InfiniteMarquee from '@/components/InfiniteMarquee';

const outfit = Outfit({ 
  subsets: ['latin'],
  weight: ['400', '600', '700', '800'] 
});

function AppLayout({ children }: { children: React.ReactNode }) {
  const { isModalOpen, closeModal } = useModal();

  return (
    <html lang="en">
      <body className={`${outfit.className} bg-background-dark text-white`}>
        <Navbar />
        <main className="flex-grow">
          {children}
        </main>
        <InfiniteMarquee speed="25s">
          <span className="text-[clamp(5rem,12vw,15rem)] font-extrabold uppercase text-white tracking-[-0.03em] mx-4">TECH WITH SOUL -</span>
        </InfiniteMarquee>
        <Footer />
        <ContactModal isOpen={isModalOpen} onClose={closeModal} />
      </body>
    </html>
  );
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <ModalProvider>
      <AppLayout>{children}</AppLayout>
    </ModalProvider>
  );
}
